mapper.update:
UPDATE tb_outbox_events
   SET next_retry_at = #{leaseUntil}
 WHERE id = #{eventId}

UPDATE tb_outbox_events
   SET status = 'PENDING',
       retry_count = #{retryCount},
       next_retry_at = #{nextRetryAt},
       error_message = #{failureCode}
 WHERE id = #{eventId}
   AND status = 'PENDING'
   AND next_retry_at = #{leaseUntil}

UPDATE tb_outbox_events
   SET status = 'FAILED',
       retry_count = #{retryCount},
       next_retry_at = NULL,
       error_message = #{failureCode}
 WHERE id = #{eventId}
   AND status = 'PENDING'
   AND next_retry_at = #{leaseUntil}
